"""Generated by appium-ai-mobile-agent from an exploration of: Sign in, add Wireless Earbuds to the cart, open the cart and checkout"""

import json
import os

import pytest
from appium import webdriver
from appium.options.common import AppiumOptions
from appium.webdriver.common.appiumby import AppiumBy
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.support.ui import WebDriverWait

pytestmark = pytest.mark.device


@pytest.fixture
def driver():
    caps = json.load(open('caps/android-emulator.json'))
    d = webdriver.Remote(os.environ.get("APPIUM_SERVER", "http://127.0.0.1:4723"), options=AppiumOptions().load_capabilities(caps))
    yield d
    d.quit()


def test_sign_in_add_wireless_earbuds_to_the_cart_open_the_cart_and_c(driver):
    wait = WebDriverWait(driver, 15)
    el = wait.until(EC.element_to_be_clickable((AppiumBy.ID, 'com.shoplite:id/email')))
    el.clear()
    el.send_keys('demo@shoplite.test')
    el = wait.until(EC.element_to_be_clickable((AppiumBy.ID, 'com.shoplite:id/password')))
    el.clear()
    el.send_keys(os.environ['TEST_PASSWORD'])
    wait.until(EC.element_to_be_clickable((AppiumBy.ID, 'com.shoplite:id/submit_signin'))).click()
    wait.until(EC.element_to_be_clickable((AppiumBy.ACCESSIBILITY_ID, 'Add Wireless Earbuds to cart'))).click()
    wait.until(EC.element_to_be_clickable((AppiumBy.ID, 'com.shoplite:id/open_cart'))).click()
    wait.until(EC.element_to_be_clickable((AppiumBy.ID, 'com.shoplite:id/checkout'))).click()
    # same check the agent used: success text anywhere on screen, ignoring case (Android buttons are often ALL CAPS)
    assert wait.until(lambda d: 'order placed' in d.page_source.lower())
